// These tests are skipped when the ESS credentials are not configured.
import LeavePage from '../support/pages/LeavePage';
import NavigationComponent from '../support/pages/NavigationComponent';

const hasEssCredentials = () =>
  Cypress.env('ORANGEHRM_ESS_USERNAME') && Cypress.env('ORANGEHRM_ESS_PASSWORD');

describe('Leave Management — Extended Coverage', () => {

  describe('@boundary — Date and Form Validation', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToLeave();
    });

    // Feature: Leave request with same from/to date (single day)
    it('@boundary — Apply Leave form accepts single-day request (from date equals to date)', function () {
      if (!hasEssCredentials()) {
        this.skip(); // REQUIRES_ESS_USER — Admin has no leave balance in demo
      }

      NavigationComponent.navigateToApplyLeave();
      LeavePage.verifyApplyLeavePageIsDisplayed();

      cy.fixture('leave').then((data) => {
        LeavePage
          .selectLeaveType(data.leaveRequest.leaveType)
          .enterFromDate(data.leaveRequest.fromDate)
          .enterToDate(data.leaveRequest.fromDate) // Same date = single day
          .clickApply();

        LeavePage.verifySuccessToast();
      });
    });

    // Feature: From date after To date shows validation error
    it('@boundary — Apply Leave rejects from date that is after to date', function () {
      if (!hasEssCredentials()) {
        this.skip(); // REQUIRES_ESS_USER
      }

      NavigationComponent.navigateToApplyLeave();
      LeavePage.verifyApplyLeavePageIsDisplayed();

      cy.fixture('leave').then((data) => {
        LeavePage
          .selectLeaveType(data.leaveRequest.leaveType)
          .enterFromDate('2027-01-20') // After to date
          .enterToDate('2027-01-15')   // Before from date
          .clickApply();

        // Expect validation error — exact message depends on OrangeHRM version
        cy.get('[role="alert"], .oxd-input-field-error-message').should('be.visible');
      });
    });

    // Feature: Submit Apply Leave without selecting Leave Type
    it('@boundary — Apply Leave requires Leave Type selection', function () {
      if (!hasEssCredentials()) {
        this.skip(); // REQUIRES_ESS_USER
      }

      NavigationComponent.navigateToApplyLeave();
      LeavePage.verifyApplyLeavePageIsDisplayed();
      LeavePage.clickApply(); // Submit without any selection

      cy.get('.oxd-input-field-error-message').should('be.visible');
    });
  });

  describe('@error — Edge Cases and Error States', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToLeave();
    });

    // Feature: Admin with no leave entitlements sees informational message (COVERED in orangehrm-leave.cy.js)
    // Included here for @error tagging completeness
    it('@error — Admin user with no leave balance sees "No Leave Types" message on Apply Leave', () => {
      NavigationComponent.navigateToApplyLeave();
      LeavePage
        .verifyApplyLeavePageIsDisplayed()
        .verifyNoLeaveTypesMessage();
    });

    // Feature: Leave list renders with empty state when no records match filter
    it('@error — Leave list shows empty state when no records match the filter', () => {
      LeavePage.verifyLeaveListPageIsDisplayed();
      LeavePage.verifyLeaveTableIsVisible();
      // The table is shown — an empty result set should not cause a JS error
      cy.get('.oxd-table').should('be.visible');
      cy.get('body').should('not.contain', 'Uncaught');
    });
  });

  describe('@state — Leave Lifecycle', () => {
    // NOTE: State scenarios (cancel, reject) require manager role or API manipulation.
    // These are structured as pending tests — implement when a manager account is available.

    it('@state — [PENDING] Cancelling a pending leave request restores leave balance', function () {
      // REQUIRES: A pending leave request + manager or employee with cancel permission
      // Implementation: API call to create leave → cancel via UI → verify balance restored
      this.skip();
    });

    it('@state — [PENDING] Rejected leave request does not consume leave balance', function () {
      // REQUIRES: Manager account to reject a pending leave
      // Implementation: ESS user applies → manager rejects → verify ESS balance unchanged
      this.skip();
    });

    it('@state — [PENDING] Duplicate leave for same dates is handled without double-deduction', function () {
      // REQUIRES: ESS user account with leave balance
      // Implementation: Submit leave for date range → submit same range → verify single deduction
      this.skip();
    });
  });

  describe('@security — Authorization', () => {
    it('@security — Unauthenticated user navigating to Leave List is redirected to login', () => {
      // Do not login — attempt direct URL access
      cy.visit('/leave/viewLeaveList', { failOnStatusCode: false });
      cy.url().should('include', '/auth/login');
      cy.get('input[name="username"]').should('be.visible');
    });
  });

  describe('@contract — API Behavior', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToLeave();
    });

    it('@contract — Leave List API response renders table without JS errors', () => {
      cy.intercept('GET', '**/leave/**').as('leaveApi');

      cy.visit('/leave/viewLeaveList', { failOnStatusCode: false });

      cy.wait('@leaveApi').then((interception) => {
        // API must not return a 5xx error
        expect(interception.response.statusCode).to.be.lessThan(500);
      });

      LeavePage.verifyLeaveTableIsVisible();
      cy.get('body').should('not.contain', 'Error');
    });
  });
});
